INSERT INTO sea_pack.ai_template_variable (`id`,`template_id`,`var_name`,`label`,`var_type`,`required`,`default_value`,`options`,`placeholder`,`sort_order`,`created_at`) VALUES (46,12,'sourceLang','源语言','select',1,'中文','[{\"label\": \"中文\", \"value\": \"中文\"}, {\"label\": \"英文\", \"value\": \"英文\"}, {\"label\": \"日文\", \"value\": \"日文\"}, {\"label\": \"韩文\", \"value\": \"韩文\"}]','请选择源语言',2,'2026-07-20 10:18:31');
